def max_path_sum(triangle, row, col):
    if row == len(triangle) - 1:
        return triangle[row][col]
    up_left = triangle[row][col] + max_path_sum(triangle, row + 1, col)
    up_right = triangle[row][col] + max_path_sum(triangle, row + 1, col + 1)
    return max(up_left, up_right)

