def find_last_occurrence(arr, num):  
    left = 0  
    right = len(arr) - 1  
    while left <= right:  
        mid = (left + right) // 2  
        if arr[mid] > num:  
            right = mid - 1  
        elif arr[mid] < num:  
            left = mid + 1  
        else:  
            if mid == len(arr) - 1 or arr[mid + 1] != num:  
                return mid  
            else:  
                left = mid + 1  
    return -1

