def find_minimum_range(arrays):
    min_range = float('inf')
    min_start = float('inf')
    max_end = float('-inf')

    for i in range(len(arrays[0])):
        current_min = float('inf')
        current_max = float('-inf')

        for j in range(len(arrays)):
            current_min = min(current_min, arrays[j][i])
            current_max = max(current_max, arrays[j][i])

        if current_min < min_start:
            min_start = current_min
        if current_max > max_end:
            max_end = current_max

        current_range = max_end - min_start
        if current_range < min_range:
            min_range = current_range

    return min_start, max_end

