def trim_tuple(tup_list, k):  
    new_tup_list = []  
    for tup in tup_list:  
        new_tup = tuple(tup[i+k:] for i in range(len(tup)))  
        new_tup_list.append(new_tup)  
    return new_tup_list

def index_multiplication(t1, t2):  
