def find_peak(arr, n):  
    for i in range(n):  
        if i == 0:  
            if arr[i] > arr[i + 1]:  
                return i  
        elif i == n - 1:  
            if arr[i] > arr[i - 1]:  
                return i  
        else:  
            if arr[i] > arr[i - 1] and arr[i] > arr[i + 1]:  
                return i  
    return -1

def max_product(arr, n):  
    max_product = 1  
    for i in range(n):  
        product = 1  
        for j in range(i, n):  
            product *= arr[j]  
            if product > max_product:  
                max_product = product  
    return max_product

def max_profit(prices, k):  
    n = len(prices)  
    if n == 0:  
        return 0  
    if k >= n:  
        return sum(prices)  
    dp = [[0] * n for _ in range(k + 1)]  
    for i in range(1, k + 1):  
        max_diff = -prices[0]  
        for j in range(1, n):  
            dp[i][j] = max(dp[i][j - 1], prices[j] + max_diff)  
            max_diff = max(max_diff, dp[i - 1][j] - prices[j])  
    return dp[k][n - 1]

def add_pairwise(tup):  
