def get_max_occuring_char(string):
    char_count = {}
    for char in string:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    max_char = ""
    max_count = 0
    for char, count in char_count.items():
        if count > max_count:
            max_char = char
            max_count = count
    return max_char

def is_subset_sum(arr, n, sum):  
    if sum == 0:  
        return True  
    if n == 0 and sum != 0:  
        return False  
    if arr[n-1] > sum:  
        return is_subset_sum(arr, n-1, sum)  
    return is_subset_sum(arr, n-1, sum) or is_subset_sum(arr, n-1, sum-arr[n-1])

