def largest_palindrome(arr, n):  
    largest = 0  
    for i in range(n):  
        num = arr[i]  
        rev = 0  
        temp = num  
        while temp > 0:  
            rev = (rev * 10) + (temp % 10)  
            temp = temp // 10  
        if num == rev and num > largest:  
            largest = num  
    return largest

def binomial_probability(n, k, p):  
    from math import comb  
    return comb(n, k) * (p ** k) * ((1 - p) ** (n - k))

