def extract_symmetric(tup_list):  
    symmetric_pairs = set()
    for tup in tup_list:
        if tup[0] == tup[1]:
            symmetric_pairs.add(tup)
        elif tup[0] == tup[1] - 1:
            symmetric_pairs.add((tup[0], tup[1]))
        elif tup[0] == tup[1] + 1:
            symmetric_pairs.add((tup[0], tup[1]))
    return symmetric_pairs

def sum_gp(a, n, r):  
    sum = 0
    for i in range(n):
        sum += a * (r ** i)
    return sum

def binary_search(arr, target):  
    low = 0  
    high = len(arr) - 1  
    while low <= high:  
        mid = (low + high) // 2  
        if arr[mid] == target:  
            return True  
        elif arr[mid] < target:  
            low = mid + 1  
        else:  
            high = mid - 1  
    return False

def binary_to_integer(binary_tuple):  
    integer = 0  
    for i in range(len(binary_tuple)):  
        integer += binary_tuple[i] * 2 ** (len(binary_tuple) - i - 1)  
    return integer

